// ---------- Persistence helpers ----------
async function storeGet(key, shared, fallback) {
  try {
    if (window.storage && window.storage.get) {
      const v = await window.storage.get(key, shared);
      if (v !== undefined && v !== null) return v;
      return fallback;
    }
  } catch (e) {}
  try {
    const v = localStorage.getItem(key);
    if (v) return JSON.parse(v);
  } catch (e) {}
  return fallback;
}
async function storeSet(key, shared, value) {
  try {
    if (window.storage && window.storage.set) { await window.storage.set(key, value, shared); return; }
  } catch (e) {}
  try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) {}
}

async function loadSeen(level) {
  return await storeGet(`y10examprep-seen-${level}-v2`, false, []);
}
async function saveSeen(level, ids) {
  await storeSet(`y10examprep-seen-${level}-v2`, false, ids);
}
async function loadFeedback() {
  return await storeGet('y10examprep-feedback-v1', true, []);
}
async function saveFeedback(list) {
  await storeSet('y10examprep-feedback-v1', true, list);
}

function shuffleArr(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

// ---------- Maths text renderer ----------
// Turns plain-text maths notation (x^2, 3/4, etc.) into proper exam-style
// typesetting — real superscripts and stacked fractions — no LaTeX markup,
// just clean symbols like you'd see printed on a past paper.
function MathText({ text }) {
  if (text === null || text === undefined) return null;
  const str = String(text);
  const re = /([A-Za-z0-9πœ\)\]])\^(\{-?\d+\}|-?\d+)|(-?\d+)\/(\d+)(?!\d*\s*(?:cm|mm|m|km|kg|g|ml|l|s|hr|hrs|min|%))/g;
  const nodes = [];
  let last = 0, m, key = 0;
  while ((m = re.exec(str))) {
    if (m.index > last) nodes.push(str.slice(last, m.index));
    if (m[1] !== undefined) {
      let exp = m[2];
      if (exp.startsWith('{')) exp = exp.slice(1, -1);
      nodes.push(m[1]);
      nodes.push(<sup key={key++} style={{ fontSize: '0.72em' }}>{exp}</sup>);
    } else {
      nodes.push(
        <span key={key++} style={{ display: 'inline-flex', flexDirection: 'column', alignItems: 'center', verticalAlign: 'middle', fontSize: '0.78em', lineHeight: 1.05, margin: '0 1px', position: 'relative', top: '0.08em' }}>
          <span style={{ borderBottom: '1.4px solid currentColor', padding: '0 3px' }}>{m[3]}</span>
          <span style={{ padding: '0 3px' }}>{m[4]}</span>
        </span>
      );
    }
    last = re.lastIndex;
  }
  if (last < str.length) nodes.push(str.slice(last));
  return <>{nodes}</>;
}

