const FLOAT_SYMBOLS = ['π', '√', 'Σ', '÷', '×', '∞', '%', '∠', 'θ', '=', '²', '∫'];

function FloatingBackground() {
  const items = React.useMemo(() => Array.from({ length: 16 }, (_, i) => ({
    sym: FLOAT_SYMBOLS[i % FLOAT_SYMBOLS.length],
    left: Math.random() * 100,
    size: 18 + Math.random() * 28,
    duration: 14 + Math.random() * 16,
    delay: -Math.random() * 20,
  })), []);
  return (
    <div className="float-layer">
      {items.map((it, i) => (
        <span
          key={i}
          className="float-sym"
          style={{ left: `${it.left}%`, fontSize: `${it.size}px`, animationDuration: `${it.duration}s`, animationDelay: `${it.delay}s` }}
        >
          {it.sym}
        </span>
      ))}
    </div>
  );
}

function Burst({ colors }) {
  const dots = React.useMemo(() => Array.from({ length: 14 }, (_, i) => {
    const angle = (Math.PI * 2 * i) / 14 + Math.random() * 0.4;
    const dist = 40 + Math.random() * 30;
    return {
      tx: Math.cos(angle) * dist,
      ty: Math.sin(angle) * dist,
      color: colors[i % colors.length],
      delay: Math.random() * 0.1,
    };
  }), [colors]);
  return (
    <span className="burst-wrap">
      {dots.map((d, i) => (
        <span key={i} className="burst-dot" style={{ '--tx': `${d.tx}px`, '--ty': `${d.ty}px`, background: d.color, animationDelay: `${d.delay}s` }} />
      ))}
    </span>
  );
}

